def js():
    out = []
    for sid, d in SC.items():
        mod = importlib.import_module(d['mod']); importlib.reload(mod)
        fs = [s['f'] for s in mod.SLIDES]
        roles = sum((len(r) for *_, r in d['flow']), 0)
        assert roles == len(fs), (sid, roles, len(fs))
        k = 0; flow = []
        for key, name, goal, rs in d['flow']:
            pairs = []
            for r in rs: pairs.append([fs[k], r]); k += 1
            flow.append(f'      st({J(key)}, {J(name)}, {J(goal)}, {J(pairs)}),')
        o = [
            '  {',
            f"    id: '{sid}', req: 'std', ind: '{d['ind']}', strategy: 'value', ending: 'workshop', minutes: {d['minutes']}, std: true,",
            f"    title: {J(d['title'])},", f"    short: {J(d['short'])},", f"    situation: {J(d['situation'])},",
            f"    signals: {J(d['signals'])},", f"    audience: {J(d['audience'])},", f"    criteria: {J(d['criteria'])},",
            f"    thesis: {J(d['thesis'])},", f"    logic: {J(d['logic'])},", f"    diff: {J(d['diff'])},",
            "    tone: '표준 양식의 언어로 · 공간 장면과 공식 사진 중심',", f"    messages: {J(d['messages'])},",
            '    flow: [', *flow, '    ],',
            f"    ask: {J(d['ask'])},", f"    next: {J(d['next'])},", f"    prep: {J(d['prep'])},",
            f"    products: {J(d['products'])}, solutions: {J(d['solutions'])}, cases: {J(d['cases'])},",
            f"    kpis: {J(d['kpis'])},", f"    objections: {J(d['objections'])},",
            f"    fit: {J(d['fit'])}, avoid: {J(d['avoid'])},",
            '  },']
        out.append('\n'.join(o))
    return '\n'.join(out) + '\n'

if __name__ == '__main__':
    print(js()[:3000])

